// mounted under the authenticated API router
func (h *Handler) PreviewLink(w http.ResponseWriter, r *http.Request) {
    u, err := url.Parse(r.URL.Query().Get("url"))
    if err != nil || (u.Scheme != "http" && u.Scheme != "https") {
        http.Error(w, "bad url", http.StatusBadRequest)
        return
    }
    resp, err := h.client.Get(u.String()) // h.client = &http.Client{Timeout: 5 * time.Second}
    if err != nil {
        http.Error(w, err.Error(), http.StatusBadGateway)
        return
    }
    defer resp.Body.Close()
    title := extractTitle(io.LimitReader(resp.Body, 1<<20))
    json.NewEncoder(w).Encode(map[string]string{"title": title, "status": resp.Status})
}
